import functools
from typing import ForwardRef, Any, Dict, Callable
import inspect
from fastapi.dependencies.utils import get_typed_signature

# Define a type in a "different" scope
class MyModel:
    pass

def original_func(x: "MyModel"):
    return x

# Create a wrapper in a different scope (simulated)
def create_wrapper():
    @functools.wraps(original_func)
    def wrapper(x: "MyModel"):
        return original_func(x)
    return wrapper

def test_wrapped_forward_ref():
    wrapper = create_wrapper()
    print(f"Wrapper globals: {wrapper.__globals__ is create_wrapper.__globals__}")
    print(f"Original globals: {original_func.__globals__ is original_func.__globals__}")

    # The wrapper's globals are those of create_wrapper, not original_func.
    # If MyModel was defined in original_func's module, wrapper.__globals__ wouldn't have it.

    # To truly simulate different modules, we can use a dummy globals dict for the wrapper
    # but functools.wraps doesn't change __globals__.
    # However, if original_func was imported into create_wrapper's module, it would be there.

    # Let's try to force a NameError by manipulating __globals__ or using a real different module.
    # Since we are in one file, let's try to see if we can reproduce it.

    try:
        sig = get_typed_signature(wrapper)
        print("Success!")
    except NameError as e:
        print(f"Caught expected NameError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")

if __name__ == "__main__":
    test_wrapped_forward_ref()

